"use client";
import { ExternalLink,ShoppingBag } from "lucide-react";import type { QChatProductCardNode,QChatUINode } from "@qchat/core";import { useQChatGeneratedUI,useQChatSelector } from "../provider/qchat-provider";
export function QChatGeneratedUI(){const {document,generating}=useQChatGeneratedUI();if(generating)return <div className="qchat-ui-loading" aria-live="polite"><span/><span/><span/><p>Compiling interface</p></div>;if(!document)return null;return <section className={`qchat-generated ${document.layout}`} aria-label="Generated interface">{document.children.map((node)=><Node key={node.id} node={node}/>)}</section>}
function Node({node}:{readonly node:QChatUINode}){if(node.type==="product-collection")return <div className="qchat-collection"><h3>{node.title}</h3><div className={node.direction}>{node.items.map((card)=><ProductCard key={card.id} card={card}/>)}</div></div>;if(node.type==="product-card")return <ProductCard card={node}/>;return <div className={`qchat-status ${node.variant}`}><strong>{node.title}</strong>{node.description&&<p>{node.description}</p>}</div>}
function ProductCard({card}:{readonly card:QChatProductCardNode}){const selections=useQChatSelector((s)=>s.selections);const select=useQChatSelector((s)=>s.select);const dispatch=useQChatSelector((s)=>s.dispatchAction);const price=new Intl.NumberFormat(undefined,{style:"currency",currency:card.price.currency}).format(card.price.amount);return <article className="qchat-product">{card.image&&<img src={card.image.src} alt={card.image.alt}/>}<div className="qchat-product-body">{card.tags&&<div className="qchat-tags">{card.tags.map((tag)=><span key={tag}>{tag}</span>)}</div>}<div className="qchat-product-heading"><h4>{card.title}</h4><strong>{price}</strong></div>{card.description&&<p>{card.description}</p>}{card.colors&&<Choice label="Color" cardId={card.id} options={card.colors} selected={selections[`${card.id}:color`]} onSelect={(value)=>select(`${card.id}:color`,value)}/>} {card.sizes&&<Choice label="Size" cardId={card.id} options={card.sizes} selected={selections[`${card.id}:size`]} onSelect={(value)=>select(`${card.id}:size`,value)}/>}<div className="qchat-product-actions">{card.primaryAction&&<button onClick={()=>void dispatch({name:card.primaryAction!.name,sourceNodeId:card.id,payload:{...card.primaryAction!.payload,color:selections[`${card.id}:color`]??"",size:selections[`${card.id}:size`]??""}})}><ShoppingBag size={15}/>{card.primaryAction.label}</button>}{card.secondaryAction&&<button className="secondary" onClick={()=>void dispatch({name:card.secondaryAction!.name,sourceNodeId:card.id,payload:card.secondaryAction!.payload})}>{card.secondaryAction.label}<ExternalLink size={14}/></button>}</div></div></article>}
function Choice({label,cardId,options,selected,onSelect}:{readonly label:string;readonly cardId:string;readonly options:readonly {value:string;label:string;color?:string;disabled?:boolean}[];readonly selected?:string;readonly onSelect:(value:string)=>void}){return <fieldset className="qchat-choice"><legend>{label}</legend><div>{options.map((option)=><button key={option.value} type="button" disabled={option.disabled} aria-pressed={selected===option.value} aria-label={`${label} ${option.label}`} onClick={()=>onSelect(option.value)}>{option.color&&<span style={{backgroundColor:option.color}}/>}{option.label}</button>)}</div></fieldset>}
