"use client";
import { QChatGeneratedUI } from "./qchat-generated-ui";import { QChatMessage } from "./qchat-message";import { QChatThinking } from "./qchat-thinking";import { QChatToolActivity } from "./qchat-tool-activity";import { useQChatConfig,useQChatMessages,useQChatRunState } from "../provider/qchat-provider";
export function QChatThread(){const messages=useQChatMessages();const {error}=useQChatRunState();const {slots}=useQChatConfig();const Thread=slots?.thread??"div";const ErrorView=slots?.error;return <Thread className="qchat-thread"><div className="qchat-thread-inner">{messages.map((message)=><QChatMessage key={message.id} message={message}/>)}<QChatThinking/><QChatToolActivity/><QChatGeneratedUI/>{error&&(ErrorView?<ErrorView error={error}/>:<div role="alert" className="qchat-error">{error.message}</div>)}</div></Thread>}
